Absolutely — here’s a tiny browser game you can play right away.

1. Copy this into a file called `cat-fish-game.html`
2. Open it in your browser
3. Use the left/right arrow keys to move the cat and catch fish

```html
<!DOCTYPE html>
<html>
<head>
  <title>Cat Catches Fish</title>
  <style>
    body {
      margin: 0;
      background: #87ceeb;
      font-family: Arial, sans-serif;
      overflow: hidden;
      text-align: center;
    }

    canvas {
      background: linear-gradient(#87ceeb, #dff7ff);
      display: block;
      margin: 0 auto;
      border: 4px solid #333;
    }

    h1 {
      margin: 10px;
    }
  </style>
</head>
<body>
  <h1>🐱 Cat Catches Fish 🐟</h1>
  <canvas id="gameCanvas" width="500" height="600"></canvas>

  <script>
    const canvas = document.getElementById("gameCanvas");
    const ctx = canvas.getContext("2d");

    const cat = {
      x: 220,
      y: 520,
      width: 60,
      height: 50,
      speed: 7
    };

    let fish = [];
    let score = 0;
    let lives = 3;
    let gameOver = false;

    const keys = {};

    document.addEventListener("keydown", function(event) {
      keys[event.key] = true;

      if (gameOver && event.key === "Enter") {
        restartGame();
      }
    });

    document.addEventListener("keyup", function(event) {
      keys[event.key] = false;
    });

    function createFish() {
      fish.push({
        x: Math.random() * (canvas.width - 30),
        y: -30,
        width: 30,
        height: 30,
        speed: 2 + Math.random() * 3
      });
    }

    function drawCat() {
      ctx.font = "50px Arial";
      ctx.fillText("🐱", cat.x, cat.y + 45);
    }

    function drawFish() {
      ctx.font = "30px Arial";
      for (let f of fish) {
        ctx.fillText("🐟", f.x, f.y + 30);
      }
    }

    function drawScore() {
      ctx.fillStyle = "#000";
      ctx.font = "24px Arial";
      ctx.fillText("Score: " + score, 20, 35);
      ctx.fillText("Lives: " + lives, 380, 35);
    }

    function updateCat() {
      if (keys["ArrowLeft"] && cat.x > 0) {
        cat.x -= cat.speed;
      }

      if (keys["ArrowRight"] && cat.x < canvas.width - cat.width) {
        cat.x += cat.speed;
      }
    }

    function updateFish() {
      for (let i = fish.length - 1; i >= 0; i--) {
        fish[i].y += fish[i].speed;

        const caught =
          fish[i].x < cat.x + cat.width &&
          fish[i].x + fish[i].width > cat.x &&
          fish[i].y < cat.y + cat.height &&
          fish[i].y + fish[i].height > cat.y;

        if (caught) {
          score++;
          fish.splice(i, 1);
        } else if (fish[i].y > canvas.height) {
          lives--;
          fish.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        }
      }
    }

    function drawGameOver() {
      ctx.fillStyle = "rgba(0, 0, 0, 0.7)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.font = "42px Arial";
      ctx.fillText("Game Over", 135, 260);

      ctx.font = "24px Arial";
      ctx.fillText("Final Score: " + score, 175, 310);
      ctx.fillText("Press Enter to Restart", 135, 360);
    }

    function restartGame() {
      fish = [];
      score = 0;
      lives = 3;
      cat.x = 220;
      gameOver = false;
    }

    let fishTimer = 0;

    function gameLoop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (!gameOver) {
        updateCat();
        updateFish();

        fishTimer++;
        if (fishTimer > 45) {
          createFish();
          fishTimer = 0;
        }

        drawCat();
        drawFish();
        drawScore();
      } else {
        drawCat();
        drawFish();
        drawScore();
        drawGameOver();
      }

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
```

Controls:

- Move left: ←
- Move right: →
- Restart after game over: Enter

Tiny challenge: try changing this line:

```js
fishTimer > 45
```

to:

```js
fishTimer > 25
```

That makes fish fall more often, so the game gets harder.

