Tiny game-dev lesson: this part decides what falls:

```js
if (randomNumber < 0.15) {
  type = "goldenFish";
} else if (randomNumber < 0.35) {
  type = "bomb";
}
```

That means:

- 15% chance golden fish
- 20% chance bomb
- 65% chance normal fish

Tiny challenge: change `0.35` to `0.50` and bombs will become way more common.

Yes — we’re giving the cat a power-up. Rainbow fish 🌈 gives a temporary shield, and while the shield is active, bombs won’t take away lives.

I also made the cat glow a little when shielded, because obviously shield-cat deserves drama.

Replace everything in the **HTML** box with this:

```html
<h1>🐱 Cat Catches Fish 🐟</h1>
<p>Use ← and → arrow keys. Catch rainbow fish for a shield!</p>
<canvas id="gameCanvas" width="500" height="600"></canvas>

<style>
  body {
    margin: 0;
    background: #1b0033;
    color: white;
    font-family: Arial, sans-serif;
    text-align: center;
  }

  canvas {
    background: linear-gradient(#2b0052, #120021);
    border: 4px solid white;
  }
</style>

<script>
  const canvas = document.getElementById("gameCanvas");
  const ctx = canvas.getContext("2d");

  const cat = {
    x: 220,
    y: 520,
    width: 60,
    height: 50,
    speed: 13
  };

  let fallingThings = [];
  let score = 0;
  let lives = 3;
  let gameOver = false;
  let timer = 0;

  // Shield starts off inactive
  let shieldActive = false;
  let shieldTimer = 0;

  const keys = {};

  document.addEventListener("keydown", function(event) {
    keys[event.key] = true;

    if (gameOver && event.key === "Enter") {
      fallingThings = [];
      score = 0;
      lives = 3;
      cat.x = 220;
      gameOver = false;
      shieldActive = false;
      shieldTimer = 0;
    }
  });

  document.addEventListener("keyup", function(event) {
    keys[event.key] = false;
  });

  function createFallingThing() {
    const randomNumber = Math.random();

    let type = "normalFish";

    if (randomNumber < 0.10) {
      type = "rainbowFish";
    } else if (randomNumber < 0.22) {
      type = "goldenFish";
    } else if (randomNumber < 0.42) {
      type = "bomb";
    }

    fallingThings.push({
      x: Math.random() * (canvas.width - 30),
      y: -30,
      width: 30,
      height: 30,
      speed: 2 + Math.random() * 3,
      type: type
    });
  }

  function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!gameOver) {
      if (keys["ArrowLeft"] && cat.x > 0) {
        cat.x -= cat.speed;
      }

      if (keys["ArrowRight"] && cat.x < canvas.width - cat.width) {
        cat.x += cat.speed;
      }

      // Count down the shield
      if (shieldActive) {
        shieldTimer--;

        if (shieldTimer <= 0) {
          shieldActive = false;
        }
      }

      timer++;
      if (timer > 40) {
        createFallingThing();
        timer = 0;
      }

      for (let i = fallingThings.length - 1; i >= 0; i--) {
        fallingThings[i].y += fallingThings[i].speed;

        const caught =
          fallingThings[i].x < cat.x + cat.width &&
          fallingThings[i].x + fallingThings[i].width > cat.x &&
          fallingThings[i].y < cat.y + cat.height &&
          fallingThings[i].y + fallingThings[i].height > cat.y;

        if (caught) {
          if (fallingThings[i].type === "goldenFish") {
            score += 10;
          } else if (fallingThings[i].type === "normalFish") {
            score += 1;
          } else if (fallingThings[i].type === "rainbowFish") {
            shieldActive = true;
            shieldTimer = 300;
          } else if (fallingThings[i].type === "bomb") {
            if (!shieldActive) {
              lives -= 1;
            }
          }

          fallingThings.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        } else if (fallingThings[i].y > canvas.height) {
          if (fallingThings[i].type !== "bomb") {
            lives--;
          }

          fallingThings.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        }
      }
    }

    // Draw shield glow
    if (shieldActive) {
      ctx.beginPath();
      ctx.arc(cat.x + 30, cat.y + 30, 45, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(0, 255, 255, 0.25)";
      ctx.fill();

      ctx.strokeStyle = "cyan";
      ctx.lineWidth = 4;
      ctx.stroke();
    }

    // Draw cat
    ctx.font = "50px Arial";
    ctx.fillText("🐱", cat.x, cat.y + 45);

    // Draw falling things
    ctx.font = "30px Arial";
    for (let thing of fallingThings) {
      if (thing.type === "goldenFish") {
        ctx.fillText("🐠", thing.x, thing.y + 30);
      } else if (thing.type === "rainbowFish") {
        ctx.fillText("🌈", thing.x, thing.y + 30);
      } else if (thing.type === "bomb") {
        ctx.fillText("💣", thing.x, thing.y + 30);
      } else {
        ctx.fillText("🐟", thing.x, thing.y + 30);
      }
    }

    // Draw score, lives, and shield status
    ctx.fillStyle = "white";
    ctx.font = "24px Arial";
    ctx.fillText("Score: " + score, 20, 35);
    ctx.fillText("Lives: " + lives, 380, 35);

    if (shieldActive) {
      ctx.fillStyle = "cyan";
      ctx.fillText("Shield: ON", 190, 35);
    }

    if (gameOver) {
      ctx.fillStyle = "rgba(0,0,0,0.75)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.font = "42px Arial";
      ctx.fillText("Game Over", 135, 260);

      ctx.font = "24px Arial";
      ctx.fillText("Final Score: " + score, 175, 310);
      ctx.fillText("Press Enter to Restart", 135, 360);
    }

    requestAnimationFrame(gameLoop);
  }

  gameLoop();
</script>
```

The important new part is this:

```js
shieldActive = true;
shieldTimer = 300;
```

That turns the shield on for about 5 seconds.

And this part protects you from bombs:

```js
if (!shieldActive) {
  lives -= 1;
}
```

Meaning: “Only lose a life if the shield is not active.”

Tiny tweak you can try: change this number:

```js
shieldTimer = 300;
```

to:

```js
shieldTimer = 600;
```

That makes the shield last about twice as long.

